<?php
$states=['received'=>'Recebido','confirmed'=>'Confirmado','preparing'=>'Em preparação','ready'=>'Pronto','out_for_delivery'=>'Saiu para entrega','delivered'=>'Entregue','cancelled'=>'Cancelado','rejected'=>'Recusado'];
$descriptions=['received'=>'Pedido enviado ao estabelecimento.','confirmed'=>'O estabelecimento confirmou o pedido.','preparing'=>'Seu pedido está sendo preparado.','ready'=>$order['order_type']==='delivery'?'Pedido pronto para sair.':'Pedido pronto para retirada.','out_for_delivery'=>'O pedido está a caminho.','delivered'=>'Pedido concluído.'];
$flow=['received','confirmed','preparing','ready'];
if($order['order_type']==='delivery')$flow[]='out_for_delivery';
$flow[]='delivered';
$currentIndex=array_search($order['status'],$flow,true);
$terminal=in_array($order['status'],['cancelled','rejected'],true);
$historyByStatus=[];
foreach($history as$event)$historyByStatus[$event['status']]=$event['created_at'];
$money=fn(int$value):string=>'R$ '.number_format($value/100,2,',','.');
$typeLabels=['delivery'=>'Entrega','pickup'=>'Retirada','dine_in'=>'Pedido na mesa'];
$paymentLabels=['cash'=>'Dinheiro','pix'=>'Pix','debit'=>'Cartão de débito','credit'=>'Cartão de crédito'];
$whatsapp=preg_replace('/\D+/','',(string)($order['tenant_whatsapp']??''));
if($whatsapp&&!str_starts_with($whatsapp,'55'))$whatsapp='55'.$whatsapp;
$trackingUrl=rtrim(env('APP_URL','http://localhost'),'/').'/pedido/'.$token;
$whatsappLines=['Olá! 👋','','Gostaria de confirmar meu pedido '.$order['public_code'].'.','','*PEDIDO*',''];
foreach($items as$item){
    $whatsappLines[]=(int)$item['quantity'].'x '.$item['product_name'].' — '.$money((int)$item['line_total_cents']);
    if(!empty($item['options_text']))$whatsappLines[]='Opções: '.$item['options_text'];
    if(!empty($item['notes']))$whatsappLines[]='Obs.: '.$item['notes'];
    $whatsappLines[]='';
}
$whatsappLines[]='Subtotal: '.$money((int)$order['subtotal_cents']);
if((int)$order['delivery_fee_cents']>0)$whatsappLines[]='Entrega: '.$money((int)$order['delivery_fee_cents']);
if((int)$order['discount_cents']>0)$whatsappLines[]='Desconto: - '.$money((int)$order['discount_cents']);
if((int)$order['service_fee_cents']>0)$whatsappLines[]='Taxa de serviço: '.$money((int)$order['service_fee_cents']);
if((int)$order['convenience_fee_cents']>0)$whatsappLines[]='Taxa de conveniência: '.$money((int)$order['convenience_fee_cents']);
$whatsappLines[]='';
$whatsappLines[]='*TOTAL: '.$money((int)$order['total_cents']).'*';
$whatsappLines[]='';
$whatsappLines[]='Cliente: '.$order['customer_name'];
$whatsappLines[]='Recebimento: '.($typeLabels[$order['order_type']]??$order['order_type']);
if($order['order_type']==='delivery'&&!empty($order['address']))$whatsappLines[]='Endereço: '.$order['address'];
elseif($order['order_type']==='pickup')$whatsappLines[]='Retirada: '.($order['tenant_address']?:'no estabelecimento');
$whatsappLines[]='Pagamento: '.($paymentLabels[$order['payment_method']]??$order['payment_method']);
$whatsappLines[]='';
$whatsappLines[]='Acompanhar pedido:';
$whatsappLines[]=$trackingUrl;
$whatsappMessage=implode("\n",$whatsappLines);
?>
